package com.fitnutri.backend.records;

import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.submission.*;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import static org.junit.jupiter.api.Assertions.*;

class ExerciseCreationIntegrationTest extends PostgresIntegrationSupport {
    @Autowired ExerciseRecordService service;@Autowired ExerciseEstimateService estimates;@Autowired ExerciseRecordRepository records;@Autowired ActivityDatasetRepository datasets;@Autowired ExerciseTypeRepository types;@Autowired UserRepository users;@Autowired UserProfileRepository profiles;@Autowired ProfileService profileService;@Autowired WeightService weightService;@Autowired WeightEntryRepository weights;@Autowired SubmissionReceiptRepository receipts;
    private User owner(int birth){var u=new User();u.setEmail("exercise-"+UUID.randomUUID()+"@example.test");u.setDisplayName("Synthetic exercise");u.setPasswordHash("not-a-login-credential");u=users.saveAndFlush(u);profileService.completeOnboarding(u.getId(),new CompleteOnboardingRequest(u.getVersion(),null,"Synthetic exercise",birth,true,Sex.PREFER_NOT_TO_SAY,new BigDecimal("170"),ActivityLevel.LIGHT,null,null,EnergyUnit.KJ,HealthSafetyAnswer.NO,false,"Australia/Sydney",new CompleteOnboardingRequest.InitialWeight(LocalDate.of(2020,1,2),new BigDecimal("70"))));return u;}
    private ExerciseType type() throws Exception {var d=new ActivityDataset();d.setName("SYNTHETIC_EXERCISE_TEST_ONLY");d.setRelease("test");d.setRevision(UUID.randomUUID().toString());d.setSourceUrl("https://example.test/activity-fixture");d.setContentSha256(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest("Synthetic exercise MET3.5".getBytes(StandardCharsets.UTF_8))));d.setSourceNote("Synthetic formula/transaction fixture only, not official facts");d.setVerified(true);d.setMinAge(19);d.setMaxAge(59);datasets.saveAndFlush(d);var t=new ExerciseType();t.setDataset(d);t.setActivityKey("synthetic-"+UUID.randomUUID());t.setDisplayName("Synthetic activity");t.setSourceActivityCode("99901");t.setSourceDescription("Synthetic general activity");t.setMetValue(new BigDecimal("3.50"));t.setActive(true);return types.saveAndFlush(t);}
    private ExerciseEstimateResponse preview(User u,ExerciseType t,LocalDate day,String minutes){return estimates.estimate(u.getId(),t.getId(),day,new BigDecimal(minutes),"Australia/Sydney");}
    private CreateExerciseRecordRequest request(ExerciseEstimateResponse p){return new CreateExerciseRecordRequest(UUID.randomUUID(),p.recordDate(),"Australia/Sydney",RecordSource.MANUAL,p.exerciseType().id(),p.durationMinutes(),UUID.randomUUID(),p.calculationFingerprint());}
    private ExerciseRecord saved(SubmissionReceiptResponse proof){return records.findById(Long.valueOf(proof.records().getFirst().id())).orElseThrow();}
    @Test void datedWeightChangesAcrossRecordDatesAndFractionalMinutesStayExact() throws Exception {var u=owner(1990);var t=type();weightService.upsertByDate(u.getId(),new AddWeightRequest(LocalDate.of(2020,1,3),new BigDecimal("80"),null,"Australia/Sydney"));var before=preview(u,t,LocalDate.of(2020,1,2),"10");var after=preview(u,t,LocalDate.of(2020,1,4),"10");assertEquals(new BigDecimal("170.847"),before.estimatedKj());assertEquals(new BigDecimal("195.253"),after.estimatedKj());assertEquals(LocalDate.of(2020,1,2),before.weightDateUsed());assertEquals(LocalDate.of(2020,1,3),after.weightDateUsed());var row=saved(service.confirmExercise(u.getId(),request(preview(u,t,LocalDate.of(2020,1,2),"10.50"))));assertEquals(new BigDecimal("10.50"),row.getDurationMinutes());assertEquals(new BigDecimal("179.389"),row.getEstimatedKj());assertEquals(new BigDecimal("70.00"),row.getWeightKgUsed());assertEquals(new BigDecimal("3.50"),row.getMetUsed());assertEquals(ExerciseEstimateService.FORMULA_VERSION,row.getFormulaVersion());assertEquals(DataQuality.CURRENT,row.getDataQuality());assertNull(row.getIntensity());assertNull(row.getEstimatedCalories());}
    @Test void activityBeforeFirstWeightIsSavedWithNullEnergyAndMissingStatus() throws Exception {var u=owner(1990);var t=type();var p=preview(u,t,LocalDate.of(2020,1,1),"10");assertEquals(EstimateStatus.MISSING_WEIGHT,p.estimateStatus());assertNull(p.estimatedKj());var row=saved(service.confirmExercise(u.getId(),request(p)));assertEquals(EstimateStatus.MISSING_WEIGHT,row.getEstimateStatus());assertNull(row.getEstimatedKj());assertNull(row.getWeightKgUsed());assertNull(row.getMetUsed());assertNull(row.getIntensity());}
    @Test void sourceAgeFailureTakesPriorityAndIsStillAValidRecordedActivity() throws Exception {var u=owner(2002);var t=type();var p=preview(u,t,LocalDate.of(2020,1,1),"10");assertEquals(EstimateStatus.NO_APPLICABLE_REFERENCE,p.estimateStatus());assertNull(p.weightKgUsed());var row=saved(service.confirmExercise(u.getId(),request(p)));assertEquals(EstimateStatus.NO_APPLICABLE_REFERENCE,row.getEstimateStatus());assertNull(row.getEstimatedKj());assertEquals(1,records.findByUserIdOrderByRecordedAtDesc(u.getId()).size());}
    @Test void weightCorrectionAfterReviewReturnsNewPreviewAndRollsBackRecordAndReceipt() throws Exception {var u=owner(1990);var t=type();var p=preview(u,t,LocalDate.of(2020,1,2),"10");var request=request(p);weightService.upsertByDate(u.getId(),new AddWeightRequest(LocalDate.of(2020,1,2),new BigDecimal("80"),0L,"Australia/Sydney"));var conflict=assertThrows(CalculationChangedException.class,()->service.confirmExercise(u.getId(),request));assertEquals(new BigDecimal("195.253"),conflict.currentPreview().estimatedKj());assertNotEquals(p.calculationFingerprint(),conflict.currentPreview().calculationFingerprint());assertTrue(records.findByUserIdOrderByRecordedAtDesc(u.getId()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(u.getId(),request.submissionId()).isEmpty());var reviewed=new CreateExerciseRecordRequest(UUID.randomUUID(),request.recordDate(),request.zone(),request.source(),request.exerciseTypeId(),request.durationMinutes(),request.clientEntryId(),conflict.currentPreview().calculationFingerprint());assertEquals(new BigDecimal("195.253"),saved(service.confirmExercise(u.getId(),reviewed)).getEstimatedKj());}
    @Test void laterProfileAndWeightChangesNeverRewriteSnapshotsAndOriginalRetryStillReplays() throws Exception {var u=owner(1990);var t=type();var request=request(preview(u,t,LocalDate.of(2020,1,2),"10"));var first=service.confirmExercise(u.getId(),request);weightService.upsertByDate(u.getId(),new AddWeightRequest(LocalDate.of(2020,1,2),new BigDecimal("80"),0L,"Australia/Sydney"));var p=profiles.findById(u.getId()).orElseThrow();p.setBirthYear(2002);p.setEnergyUnit(EnergyUnit.KCAL);profiles.saveAndFlush(p);t.setActive(false);types.saveAndFlush(t);var replay=service.confirmExercise(u.getId(),request);assertTrue(replay.replayed());assertEquals(first.records(),replay.records());var row=saved(replay);assertEquals(new BigDecimal("170.847"),row.getEstimatedKj());assertEquals(new BigDecimal("70.00"),row.getWeightKgUsed());assertEquals(0,row.getVersion());}
    @Test void unrelatedDisplayChangesDoNotInvalidateReviewedCalculation() throws Exception {var u=owner(1990);var t=type();var before=preview(u,t,LocalDate.of(2020,1,2),"10");var p=profiles.findById(u.getId()).orElseThrow();p.setEnergyUnit(EnergyUnit.KCAL);profiles.saveAndFlush(p);u=users.findById(u.getId()).orElseThrow();u.setDisplayName("Different display name");users.saveAndFlush(u);assertEquals(before.calculationFingerprint(),preview(u,t,LocalDate.of(2020,1,2),"10.00").calculationFingerprint());assertFalse(service.confirmExercise(u.getId(),request(before)).replayed());}
    @Test void unknownInactiveAndFractionalOverprecisionCannotCommitNewActivities() throws Exception {var u=owner(1990);var t=type();var p=preview(u,t,LocalDate.of(2020,1,2),"10");var bad=new CreateExerciseRecordRequest(UUID.randomUUID(),p.recordDate(),"Australia/Sydney",RecordSource.MANUAL,"999999999",BigDecimal.TEN,UUID.randomUUID(),p.calculationFingerprint());assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->service.confirmExercise(u.getId(),bad)).code());var tooPrecise=new CreateExerciseRecordRequest(UUID.randomUUID(),p.recordDate(),"Australia/Sydney",RecordSource.MANUAL,t.getId().toString(),new BigDecimal("10.001"),UUID.randomUUID(),p.calculationFingerprint());assertEquals("VALIDATION_ERROR",assertThrows(BusinessException.class,()->service.confirmExercise(u.getId(),tooPrecise)).code());t.setActive(false);types.saveAndFlush(t);var inactive=request(p);assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->service.confirmExercise(u.getId(),inactive)).code());assertTrue(records.findByUserIdOrderByRecordedAtDesc(u.getId()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(u.getId(),inactive.submissionId()).isEmpty());}
    @Test void concurrentRealExerciseRetriesCreateOneDatedSnapshot() throws Exception {var u=owner(1990);var t=type();var request=request(preview(u,t,LocalDate.of(2020,1,2),"10"));var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<SubmissionReceiptResponse> work=()->{start.await();return service.confirmExercise(u.getId(),request);};var a=pool.submit(work);var b=pool.submit(work);start.countDown();var one=a.get(15,TimeUnit.SECONDS);var two=b.get(15,TimeUnit.SECONDS);assertNotEquals(one.replayed(),two.replayed());assertEquals(one.records(),two.records());assertEquals(1,records.findByUserIdOrderByRecordedAtDesc(u.getId()).size());}}
}
